    "source": "// Huffman coding — complete C++17 reference.\n#include <algorithm>\n#include <memory>\n#include <string>\n#include <vector>\n\nstruct HNode {\n    std::string ch;\n    long long freq;\n    std::shared_ptr<HNode> left, right;\n};\nusing Node = std::shared_ptr<HNode>;\n\nNode huffman(const std::vector<std::string>& symbols, const std::vector<long long>& freqs) {\n    std::vector<Node> nodes;\n    for (size_t i = 0; i < symbols.size(); i++) nodes.push_back(std::make_shared<HNode>(HNode{symbols[i], freqs[i], nullptr, nullptr}));\n    if (nodes.empty()) return nullptr;\n    while (nodes.size() > 1) {\n        std::stable_sort(nodes.begin(), nodes.end(), [](const Node& a, const Node& b) { return a->freq < b->freq; });\n        Node a = nodes.front();\n        nodes.erase(nodes.begin());\n        Node b = nodes.front();\n        nodes.erase(nodes.begin());\n        nodes.push_back(std::make_shared<HNode>(HNode{\"\", a->freq + b->freq, a, b}));\n    }\n    return nodes[0];\n}\n",
