    "source": "import java.util.ArrayList;\nimport java.util.Comparator;\nimport java.util.List;\n\n/** Huffman coding — complete Java reference. */\npublic final class Huffman {\n    public static final class HNode {\n        final String ch;\n        final long freq;\n        final HNode left, right;\n\n        HNode(String ch, long freq, HNode left, HNode right) {\n            this.ch = ch;\n            this.freq = freq;\n            this.left = left;\n            this.right = right;\n        }\n    }\n\n    public static HNode huffman(String[] symbols, long[] freqs) {\n        List<HNode> nodes = new ArrayList<>();\n        for (int i = 0; i < symbols.length; i++) nodes.add(new HNode(symbols[i], freqs[i], null, null));\n        if (nodes.isEmpty()) return null;\n        while (nodes.size() > 1) {\n            nodes.sort(Comparator.comparingLong(x -> x.freq));\n            HNode a = nodes.remove(0);\n            HNode b = nodes.remove(0);\n            nodes.add(new HNode(null, a.freq + b.freq, a, b));\n        }\n        return nodes.get(0);\n    }\n}\n",
