    "source": "/// Huffman coding — complete Rust reference.\npub struct HNode {\n    pub ch: Option<String>,\n    pub freq: u64,\n    pub left: Option<Box<HNode>>,\n    pub right: Option<Box<HNode>>,\n}\n\npub fn huffman(symbols: &[String], freqs: &[u64]) -> Option<Box<HNode>> {\n    let mut nodes: Vec<Box<HNode>> = symbols.iter().zip(freqs).map(|(ch, &freq)| Box::new(HNode { ch: Some(ch.clone()), freq, left: None, right: None })).collect();\n    if nodes.is_empty() {\n        return None;\n    }\n    while nodes.len() > 1 {\n        nodes.sort_by_key(|x| x.freq);\n        let a = nodes.remove(0);\n        let b = nodes.remove(0);\n        nodes.push(Box::new(HNode { ch: None, freq: a.freq + b.freq, left: Some(a), right: Some(b) }));\n    }\n    nodes.pop()\n}\n",
